insert into public.quiz_questions (bab_range, status, position, category, instruction, html, options, answer, explanation, material, srs_id) values
  (1, 'draft', 0, 'Cara Baca Kanji', '＿＿＿の ことばは ひらがなで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', '<u>私</u>は がくせいです。', '["わたし","あなた","かれ","どなた"]'::jsonb, 0, '私 dibaca “わたし” dan berarti saya.', 'Bab 1–5 · Mondai 1 No.1', 'kanji:私'),
  (1, 'draft', 1, 'Cara Baca Kanji', '＿＿＿の ことばは ひらがなで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', 'あのかたは <u>会社員</u>です。', '["かいしゃいん","ぎんこういん","けんきゅうしゃ","きょうし"]'::jsonb, 0, '会社員 dibaca “かいしゃいん” dan berarti pegawai perusahaan.', 'Bab 1–5 · Mondai 1 No.2', 'kanji:会社員'),
  (1, 'draft', 2, 'Cara Baca Kanji', '＿＿＿の ことばは ひらがなで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', 'わたしは <u>韓国</u>から きました。', '["かんこく","ちゅうごく","にほん","だいがく"]'::jsonb, 0, '韓国 dibaca “かんこく” dan berarti Korea.', 'Bab 1–5 · Mondai 1 No.3', 'kanji:韓国'),
  (1, 'draft', 3, 'Cara Baca Kanji', '＿＿＿の ことばは ひらがなで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', 'これは わたしの <u>辞書</u>です。', '["じしょ","ざっし","しんぶん","めいし"]'::jsonb, 0, '辞書 dibaca “じしょ” dan berarti kamus.', 'Bab 1–5 · Mondai 1 No.4', 'kanji:辞書'),
  (1, 'draft', 4, 'Cara Baca Kanji', '＿＿＿の ことばは ひらがなで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', 'その <u>新聞</u>は わたしのです。', '["しんぶん","ざっし","てちょう","めいし"]'::jsonb, 0, '新聞 dibaca “しんぶん” dan berarti koran.', 'Bab 1–5 · Mondai 1 No.5', 'kanji:新聞'),
  (1, 'draft', 5, 'Cara Baca Kanji', '＿＿＿の ことばは ひらがなで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', '<u>会議室</u>は あそこです。', '["かいぎしつ","じむしょ","きょうしつ","しょくどう"]'::jsonb, 0, '会議室 dibaca “かいぎしつ” dan berarti ruang rapat.', 'Bab 1–5 · Mondai 1 No.6', 'kanji:会議室'),
  (1, 'draft', 6, 'Cara Baca Kanji', '＿＿＿の ことばは ひらがなで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', 'エレベーターは <u>何階</u>ですか。', '["なんがい","なんかい","なんえん","なんにち"]'::jsonb, 0, '何階 dibaca “なんがい” dan berarti lantai berapa.', 'Bab 1–5 · Mondai 1 No.7', 'kanji:何階'),
  (1, 'draft', 7, 'Cara Baca Kanji', '＿＿＿の ことばは ひらがなで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', 'まいあさ 6じに <u>起きます</u>。', '["おきます","ねます","はたらきます","やすみます"]'::jsonb, 0, '起きます dibaca “おきます” dan berarti bangun tidur.', 'Bab 1–5 · Mondai 1 No.8', 'kanji:起きます'),
  (1, 'draft', 8, 'Cara Baca Kanji', '＿＿＿の ことばは ひらがなで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', 'きょうは <u>何曜日</u>ですか。', '["なんようび","なんじ","なんにち","なんがつ"]'::jsonb, 0, '何曜日 dibaca “なんようび” dan berarti hari apa.', 'Bab 1–5 · Mondai 1 No.9', 'kanji:何曜日'),
  (1, 'draft', 9, 'Cara Baca Kanji', '＿＿＿の ことばは ひらがなで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', '<u>午後</u>は かいぎです。', '["ごご","ごぜん","いま","まいにち"]'::jsonb, 0, '午後 dibaca “ごご” dan berarti sore/siang setelah jam 12.', 'Bab 1–5 · Mondai 1 No.10', 'kanji:午後'),
  (1, 'draft', 10, 'Cara Baca Kanji', '＿＿＿の ことばは ひらがなで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', '<u>友達</u>と がっこうへ いきます。', '["ともだち","かぞく","かれ","ひと"]'::jsonb, 0, '友達 dibaca “ともだち” dan berarti teman.', 'Bab 1–5 · Mondai 1 No.11', 'kanji:友達'),
  (1, 'draft', 11, 'Cara Baca Kanji', '＿＿＿の ことばは ひらがなで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', '<u>来週</u> にほんへ いきます。', '["らいしゅう","せんしゅう","こんしゅう","らいねん"]'::jsonb, 0, '来週 dibaca “らいしゅう” dan berarti minggu depan.', 'Bab 1–5 · Mondai 1 No.12', 'kanji:来週'),
  (1, 'draft', 12, 'Penulisan Kanji', '＿＿＿の ことばは かんじで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', 'あの <u>がくせい</u>は わたしの ともだちです。', '["学生","先生","医者","会社員"]'::jsonb, 0, 'がくせい ditulis 学生, berarti pelajar/mahasiswa.', 'Bab 1–5 · Mondai 2 No.13', 'kanji:学生'),
  (1, 'draft', 13, 'Penulisan Kanji', '＿＿＿の ことばは かんじで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', 'これは わたしの <u>とけい</u>です。', '["時計","眼鏡","傘","鞄"]'::jsonb, 0, 'とけい ditulis 時計, berarti jam/arloji.', 'Bab 1–5 · Mondai 2 No.14', 'kanji:時計'),
  (1, 'draft', 14, 'Penulisan Kanji', '＿＿＿の ことばは かんじで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', 'その <u>えんぴつ</u>は だれのですか。', '["鉛筆","雑誌","手帳","名刺"]'::jsonb, 0, 'えんぴつ ditulis 鉛筆, berarti pensil.', 'Bab 1–5 · Mondai 2 No.15', 'kanji:鉛筆'),
  (1, 'draft', 15, 'Penulisan Kanji', '＿＿＿の ことばは かんじで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', '<u>かいしゃ</u>は どこですか。', '["会社","事務所","教室","食堂"]'::jsonb, 0, 'かいしゃ ditulis 会社, berarti perusahaan.', 'Bab 1–5 · Mondai 2 No.16', 'kanji:会社'),
  (1, 'draft', 16, 'Penulisan Kanji', '＿＿＿の ことばは かんじで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', 'まいあさ 7じに <u>おきます</u>。', '["起きます","寝ます","働きます","終わります"]'::jsonb, 0, 'おきます ditulis 起きます, berarti bangun tidur.', 'Bab 1–5 · Mondai 2 No.17', 'kanji:起きます'),
  (1, 'draft', 17, 'Penulisan Kanji', '＿＿＿の ことばは かんじで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', '<u>にちようび</u>は やすみです。', '["日曜日","土曜日","月曜日","金曜日"]'::jsonb, 0, 'にちようび ditulis 日曜日, berarti hari Minggu.', 'Bab 1–5 · Mondai 2 No.18', 'kanji:日曜日'),
  (1, 'draft', 18, 'Penulisan Kanji', '＿＿＿の ことばは かんじで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', 'わたしは <u>でんしゃ</u>で がっこうへ いきます。', '["電車","自転車","飛行機","地下鉄"]'::jsonb, 0, 'でんしゃ ditulis 電車, berarti kereta listrik.', 'Bab 1–5 · Mondai 2 No.19', 'kanji:電車'),
  (1, 'draft', 19, 'Penulisan Kanji', '＿＿＿の ことばは かんじで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', '<u>おてあらい</u>は どこですか。', '["お手洗い","事務所","教室","食堂"]'::jsonb, 0, 'おてあらい ditulis お手洗い, berarti kamar kecil/WC.', 'Bab 1–5 · Mondai 2 No.20', 'kanji:お手洗い'),
  (1, 'draft', 20, 'Kosakata', '（　）に なにを いれますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', 'わたしは がくせい（　）。', '["です","でした","でしょう","じゃありません"]'::jsonb, 0, 'です menyatakan pernyataan positif SEKARANG: “Saya adalah pelajar.” でした berarti dulu, でしょう berarti dugaan, dan じゃありません berarti bukan - keempatnya bentuk akhir kalimat yang mirip tapi maknanya beda.', 'Bab 1–5 · Mondai 3 No.21', 'materi:book1:0:0'),
  (1, 'draft', 21, 'Kosakata', '（　）に なにを いれますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', 'あのかたは せんせい（　）。がくせいです。', '["じゃありません","です","ですか","でした"]'::jsonb, 0, 'Kalimat lanjutan “がくせいです” menegaskan bukan guru SEKARANG, jadi じゃありません (bukan, kini) yang tepat. です berarti “adalah” (positif), ですか membuatnya jadi pertanyaan, dan でした berarti dulu - ketiganya salah konteks.', 'Bab 1–5 · Mondai 3 No.22', 'materi:book1:0:0'),
  (1, 'draft', 22, 'Kosakata', '（　）に なにを いれますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', 'これは わたし（　）ほんです。', '["の","も","を","が"]'::jsonb, 0, 'の menghubungkan dua kata benda untuk kepemilikan: “buku saya.” も berarti “juga” (beda makna), sedangkan を dan が tidak bisa menyambung dua kata benda seperti ini.', 'Bab 1–5 · Mondai 3 No.23', 'materi:book1:1:0'),
  (1, 'draft', 23, 'Kosakata', '（　）に なにを いれますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', 'わたしは がくせいです。あなた（　）ですか。', '["も","の","が","に"]'::jsonb, 0, 'も berarti “juga”, menggantikan は pada topik kedua yang predikatnya sama. の di sini membuat kalimat lain (“punya Anda?”) yang tidak nyambung dengan konteks, sedangkan が dan に tidak menyatakan kesamaan seperti も.', 'Bab 1–5 · Mondai 3 No.24', 'materi:book1:1:0'),
  (1, 'draft', 24, 'Kosakata', '（　）に なにを いれますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', 'かいぎしつは（　）ですか。', '["どこ","だれ","いつ","なに"]'::jsonb, 0, 'どこ dipakai untuk menanyakan tempat.', 'Bab 1–5 · Mondai 3 No.25', 'materi:book1:2:0'),
  (1, 'draft', 25, 'Kosakata', '（　）に なにを いれますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', '「これは あなたの かさですか。」「いいえ、（　）。」', '["ちがいます","そうです","そうですか","どうも"]'::jsonb, 0, 'ちがいます dipakai untuk menyangkal informasi yang salah. そうです dan そうですか dipakai untuk jawaban POSITIF/mengerti, bukan menyangkal, dan どうも adalah ungkapan terima kasih - ketiganya salah konteks di sini.', 'Bab 1–5 · Mondai 3 No.26', 'materi:book1:2:0'),
  (1, 'draft', 26, 'Kosakata', '（　）に なにを いれますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', 'わたしは まいあさ 6じ（　）おきます。', '["に","で","と","へ"]'::jsonb, 0, 'に menandai waktu yang spesifik seperti jam.', 'Bab 1–5 · Mondai 3 No.27', 'materi:book1:3:0'),
  (1, 'draft', 27, 'Kosakata', '（　）に なにを いれますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', 'げつようび（　）きんようびまで はたらきます。', '["から","まで","と","に"]'::jsonb, 0, 'から menunjukkan titik mulai, dipasangkan dengan まで.', 'Bab 1–5 · Mondai 3 No.28', 'materi:book1:3:0'),
  (1, 'draft', 28, 'Kosakata', '（　）に なにを いれますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', 'わたしは でんしゃ（　）がっこうへ いきます。', '["で","へ","と","に"]'::jsonb, 0, 'で menandai alat transportasi yang dipakai.', 'Bab 1–5 · Mondai 3 No.29', 'materi:book1:4:0'),
  (1, 'draft', 29, 'Kosakata', '（　）に なにを いれますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', 'ともだち（　）かえります。', '["と","へ","で","の"]'::jsonb, 0, 'と menunjukkan teman yang menyertai suatu kegiatan.', 'Bab 1–5 · Mondai 3 No.30', 'materi:book1:4:0'),
  (1, 'draft', 30, 'Parafrasa', '＿＿＿の ぶんと だいたい おなじ いみの ぶんが あります。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', 'あのかたは せんせいです。', '["あのかたは がくせいです。","あのかたは きょうしです。","あのかたは いしゃです。","あのかたは かいしゃいんです。"]'::jsonb, 1, 'せんせい dan きょうし sama-sama berarti “guru”, meski きょうし lebih sering dipakai untuk menyebut profesi sendiri.', 'Bab 1–5 · Mondai 4 No.31', 'materi:book1:0:0'),
  (1, 'draft', 31, 'Parafrasa', '＿＿＿の ぶんと だいたい おなじ いみの ぶんが あります。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', 'これは わたしの ほんです。', '["この ほんは わたしのです。","その ほんは あなたのです。","あの ほんは せんせいのです。","これは あなたの ほんです。"]'::jsonb, 0, 'これは Nです dapat diubah menjadi この Nは……のです, karena これ menggantikan “ini+benda” sedangkan この menerangkan benda yang disebut.', 'Bab 1–5 · Mondai 4 No.32', 'materi:book1:1:0'),
  (1, 'draft', 32, 'Parafrasa', '＿＿＿の ぶんと だいたい おなじ いみの ぶんが あります。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', 'かいぎしつは どこですか。', '["かいぎしつは どちらですか。","かいぎしつは なんですか。","かいぎしつは だれですか。","かいぎしつは いつですか。"]'::jsonb, 0, 'どこ dan どちら sama-sama menanyakan tempat; どちら lebih sopan.', 'Bab 1–5 · Mondai 4 No.33', 'materi:book1:2:0'),
  (1, 'draft', 33, 'Parafrasa', '＿＿＿の ぶんと だいたい おなじ いみの ぶんが あります。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', 'きょうは やすみです。', '["きょうは はたらきます。","きょうは はたらきません。","きょうは べんきょうします。","きょうは おわります。"]'::jsonb, 1, 'やすみ (hari libur) berarti tidak bekerja, jadi はたらきません paling sesuai.', 'Bab 1–5 · Mondai 4 No.34', 'materi:book1:3:0'),
  (1, 'draft', 34, 'Parafrasa', '＿＿＿の ぶんと だいたい おなじ いみの ぶんが あります。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', 'わたしは ひとりで がっこうへ いきます。', '["わたしは ともだちと がっこうへ いきます。","わたしは かぞくと がっこうへ いきます。","わたしは だれとも がっこうへ いきません。","わたしは ともだちと かえります。"]'::jsonb, 2, 'ひとりで (sendirian) berarti tidak pergi bersama siapa pun, sepadan dengan だれとも～ません.', 'Bab 1–5 · Mondai 4 No.35', 'materi:book1:4:0'),
  (1, 'draft', 35, 'Soal Cerita', 'Baca cerita pendek berikut, lalu jawab pertanyaannya.', 'ミラーさんは　IMCの　会社員です。学生じゃ　ありません。これは　ミラーさんの　傘ですか。……いいえ、違います。それは　山田さんのです。<br><small>この　傘は　だれのですか。</small>', '["ミラーさんの","山田さんの","IMCの","学生の"]'::jsonb, 1, 'Cerita menjawab langsung: “Apakah ini payung Miller?……Bukan, itu payung Yamada.” の menggantikan Kata Benda yang sudah disebut (Pel.1–2), jadi 山田さんの berarti “punya Sdr. Yamada”.', 'Bab 1–5 · Soal Cerita No.36', 'materi:book1:1:0'),
  (1, 'draft', 36, 'Soal Cerita', 'Baca cerita pendek berikut, lalu jawab pertanyaannya.', 'この　本は　わたしのです。あの　コンピューターは　どこの　コンピューターですか。……日本の　コンピューターです。会社の　事務所は　2階です。<br><small>事務所は　どこですか。</small>', '["1階","2階","3階","4階"]'::jsonb, 1, 'Kalimat terakhir cerita menyebutkan “Kantor perusahaan di lantai 2”, memakai pola Kata Benda は tempat です (Pel.3) untuk menyatakan lokasi.', 'Bab 1–5 · Soal Cerita No.37', 'materi:book1:2:0'),
  (1, 'draft', 37, 'Soal Cerita', 'Baca cerita pendek berikut, lalu jawab pertanyaannya.', 'お手洗いは　あそこです。銀行は　9時から　3時までです。わたしは　まいあさ　6時に　おきます。<br><small>銀行は　何時からですか。</small>', '["7時","8時","9時","10時"]'::jsonb, 2, 'Cerita menyatakan “Bank dari pukul 9 sampai pukul 3”, memakai pola～から～まで (Pel.4) untuk titik mulai dan titik akhir waktu.', 'Bab 1–5 · Soal Cerita No.38', 'materi:book1:3:0'),
  (1, 'draft', 38, 'Soal Cerita', 'Baca cerita pendek berikut, lalu jawab pertanyaannya.', 'きのう　勉強しませんでした。あした　京都へ　行きます。電車で　行きます。<br><small>何で　京都へ　行きますか。</small>', '["バス","タクシー","電車","歩いて"]'::jsonb, 2, 'Kalimat terakhir cerita menyebutkan “Pergi dengan kereta rel listrik”, memakai pola Kata Benda（kendaraan）で行きます (Pel.5) untuk sarana transportasi.', 'Bab 1–5 · Soal Cerita No.39', 'materi:book1:4:0'),
  (1, 'draft', 39, 'Soal Cerita', 'Baca cerita pendek berikut, lalu jawab pertanyaannya.', '先週　どこ［へ］も　行きませんでした。今週の　日曜日、家族と　京都へ　行きます。……いいですね。<br><small>だれと　京都へ　行きますか。</small>', '["一人で","友達と","家族と","先生と"]'::jsonb, 2, 'Cerita menyebutkan “Bersama keluarga pergi ke Kyoto”, memakai pola Kata Benda（orang）と Kata Kerja (Pel.5) untuk menyatakan teman melakukan sesuatu.', 'Bab 1–5 · Soal Cerita No.40', 'materi:book1:4:0');
insert into public.quiz_questions (bab_range, status, position, category, instruction, html, options, answer, explanation, material, srs_id) values
  (1, 'published', 0, 'Cara Baca Kanji', '＿＿＿の ことばは ひらがなで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', '<u>私</u>は がくせいです。', '["わたし","あなた","かれ","どなた"]'::jsonb, 0, '私 dibaca “わたし” dan berarti saya.', 'Bab 1–5 · Mondai 1 No.1', 'kanji:私'),
  (1, 'published', 1, 'Cara Baca Kanji', '＿＿＿の ことばは ひらがなで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', 'あのかたは <u>会社員</u>です。', '["かいしゃいん","ぎんこういん","けんきゅうしゃ","きょうし"]'::jsonb, 0, '会社員 dibaca “かいしゃいん” dan berarti pegawai perusahaan.', 'Bab 1–5 · Mondai 1 No.2', 'kanji:会社員'),
  (1, 'published', 2, 'Cara Baca Kanji', '＿＿＿の ことばは ひらがなで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', 'わたしは <u>韓国</u>から きました。', '["かんこく","ちゅうごく","にほん","だいがく"]'::jsonb, 0, '韓国 dibaca “かんこく” dan berarti Korea.', 'Bab 1–5 · Mondai 1 No.3', 'kanji:韓国'),
  (1, 'published', 3, 'Cara Baca Kanji', '＿＿＿の ことばは ひらがなで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', 'これは わたしの <u>辞書</u>です。', '["じしょ","ざっし","しんぶん","めいし"]'::jsonb, 0, '辞書 dibaca “じしょ” dan berarti kamus.', 'Bab 1–5 · Mondai 1 No.4', 'kanji:辞書'),
  (1, 'published', 4, 'Cara Baca Kanji', '＿＿＿の ことばは ひらがなで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', 'その <u>新聞</u>は わたしのです。', '["しんぶん","ざっし","てちょう","めいし"]'::jsonb, 0, '新聞 dibaca “しんぶん” dan berarti koran.', 'Bab 1–5 · Mondai 1 No.5', 'kanji:新聞'),
  (1, 'published', 5, 'Cara Baca Kanji', '＿＿＿の ことばは ひらがなで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', '<u>会議室</u>は あそこです。', '["かいぎしつ","じむしょ","きょうしつ","しょくどう"]'::jsonb, 0, '会議室 dibaca “かいぎしつ” dan berarti ruang rapat.', 'Bab 1–5 · Mondai 1 No.6', 'kanji:会議室'),
  (1, 'published', 6, 'Cara Baca Kanji', '＿＿＿の ことばは ひらがなで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', 'エレベーターは <u>何階</u>ですか。', '["なんがい","なんかい","なんえん","なんにち"]'::jsonb, 0, '何階 dibaca “なんがい” dan berarti lantai berapa.', 'Bab 1–5 · Mondai 1 No.7', 'kanji:何階'),
  (1, 'published', 7, 'Cara Baca Kanji', '＿＿＿の ことばは ひらがなで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', 'まいあさ 6じに <u>起きます</u>。', '["おきます","ねます","はたらきます","やすみます"]'::jsonb, 0, '起きます dibaca “おきます” dan berarti bangun tidur.', 'Bab 1–5 · Mondai 1 No.8', 'kanji:起きます'),
  (1, 'published', 8, 'Cara Baca Kanji', '＿＿＿の ことばは ひらがなで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', 'きょうは <u>何曜日</u>ですか。', '["なんようび","なんじ","なんにち","なんがつ"]'::jsonb, 0, '何曜日 dibaca “なんようび” dan berarti hari apa.', 'Bab 1–5 · Mondai 1 No.9', 'kanji:何曜日'),
  (1, 'published', 9, 'Cara Baca Kanji', '＿＿＿の ことばは ひらがなで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', '<u>午後</u>は かいぎです。', '["ごご","ごぜん","いま","まいにち"]'::jsonb, 0, '午後 dibaca “ごご” dan berarti sore/siang setelah jam 12.', 'Bab 1–5 · Mondai 1 No.10', 'kanji:午後'),
  (1, 'published', 10, 'Cara Baca Kanji', '＿＿＿の ことばは ひらがなで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', '<u>友達</u>と がっこうへ いきます。', '["ともだち","かぞく","かれ","ひと"]'::jsonb, 0, '友達 dibaca “ともだち” dan berarti teman.', 'Bab 1–5 · Mondai 1 No.11', 'kanji:友達'),
  (1, 'published', 11, 'Cara Baca Kanji', '＿＿＿の ことばは ひらがなで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', '<u>来週</u> にほんへ いきます。', '["らいしゅう","せんしゅう","こんしゅう","らいねん"]'::jsonb, 0, '来週 dibaca “らいしゅう” dan berarti minggu depan.', 'Bab 1–5 · Mondai 1 No.12', 'kanji:来週'),
  (1, 'published', 12, 'Penulisan Kanji', '＿＿＿の ことばは かんじで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', 'あの <u>がくせい</u>は わたしの ともだちです。', '["学生","先生","医者","会社員"]'::jsonb, 0, 'がくせい ditulis 学生, berarti pelajar/mahasiswa.', 'Bab 1–5 · Mondai 2 No.13', 'kanji:学生'),
  (1, 'published', 13, 'Penulisan Kanji', '＿＿＿の ことばは かんじで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', 'これは わたしの <u>とけい</u>です。', '["時計","眼鏡","傘","鞄"]'::jsonb, 0, 'とけい ditulis 時計, berarti jam/arloji.', 'Bab 1–5 · Mondai 2 No.14', 'kanji:時計'),
  (1, 'published', 14, 'Penulisan Kanji', '＿＿＿の ことばは かんじで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', 'その <u>えんぴつ</u>は だれのですか。', '["鉛筆","雑誌","手帳","名刺"]'::jsonb, 0, 'えんぴつ ditulis 鉛筆, berarti pensil.', 'Bab 1–5 · Mondai 2 No.15', 'kanji:鉛筆'),
  (1, 'published', 15, 'Penulisan Kanji', '＿＿＿の ことばは かんじで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', '<u>かいしゃ</u>は どこですか。', '["会社","事務所","教室","食堂"]'::jsonb, 0, 'かいしゃ ditulis 会社, berarti perusahaan.', 'Bab 1–5 · Mondai 2 No.16', 'kanji:会社'),
  (1, 'published', 16, 'Penulisan Kanji', '＿＿＿の ことばは かんじで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', 'まいあさ 7じに <u>おきます</u>。', '["起きます","寝ます","働きます","終わります"]'::jsonb, 0, 'おきます ditulis 起きます, berarti bangun tidur.', 'Bab 1–5 · Mondai 2 No.17', 'kanji:起きます'),
  (1, 'published', 17, 'Penulisan Kanji', '＿＿＿の ことばは かんじで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', '<u>にちようび</u>は やすみです。', '["日曜日","土曜日","月曜日","金曜日"]'::jsonb, 0, 'にちようび ditulis 日曜日, berarti hari Minggu.', 'Bab 1–5 · Mondai 2 No.18', 'kanji:日曜日'),
  (1, 'published', 18, 'Penulisan Kanji', '＿＿＿の ことばは かんじで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', 'わたしは <u>でんしゃ</u>で がっこうへ いきます。', '["電車","自転車","飛行機","地下鉄"]'::jsonb, 0, 'でんしゃ ditulis 電車, berarti kereta listrik.', 'Bab 1–5 · Mondai 2 No.19', 'kanji:電車'),
  (1, 'published', 19, 'Penulisan Kanji', '＿＿＿の ことばは かんじで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', '<u>おてあらい</u>は どこですか。', '["お手洗い","事務所","教室","食堂"]'::jsonb, 0, 'おてあらい ditulis お手洗い, berarti kamar kecil/WC.', 'Bab 1–5 · Mondai 2 No.20', 'kanji:お手洗い'),
  (1, 'published', 20, 'Kosakata', '（　）に なにを いれますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', 'わたしは がくせい（　）。', '["です","でした","でしょう","じゃありません"]'::jsonb, 0, 'です menyatakan pernyataan positif SEKARANG: “Saya adalah pelajar.” でした berarti dulu, でしょう berarti dugaan, dan じゃありません berarti bukan - keempatnya bentuk akhir kalimat yang mirip tapi maknanya beda.', 'Bab 1–5 · Mondai 3 No.21', 'materi:book1:0:0'),
  (1, 'published', 21, 'Kosakata', '（　）に なにを いれますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', 'あのかたは せんせい（　）。がくせいです。', '["じゃありません","です","ですか","でした"]'::jsonb, 0, 'Kalimat lanjutan “がくせいです” menegaskan bukan guru SEKARANG, jadi じゃありません (bukan, kini) yang tepat. です berarti “adalah” (positif), ですか membuatnya jadi pertanyaan, dan でした berarti dulu - ketiganya salah konteks.', 'Bab 1–5 · Mondai 3 No.22', 'materi:book1:0:0'),
  (1, 'published', 22, 'Kosakata', '（　）に なにを いれますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', 'これは わたし（　）ほんです。', '["の","も","を","が"]'::jsonb, 0, 'の menghubungkan dua kata benda untuk kepemilikan: “buku saya.” も berarti “juga” (beda makna), sedangkan を dan が tidak bisa menyambung dua kata benda seperti ini.', 'Bab 1–5 · Mondai 3 No.23', 'materi:book1:1:0'),
  (1, 'published', 23, 'Kosakata', '（　）に なにを いれますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', 'わたしは がくせいです。あなた（　）ですか。', '["も","の","が","に"]'::jsonb, 0, 'も berarti “juga”, menggantikan は pada topik kedua yang predikatnya sama. の di sini membuat kalimat lain (“punya Anda?”) yang tidak nyambung dengan konteks, sedangkan が dan に tidak menyatakan kesamaan seperti も.', 'Bab 1–5 · Mondai 3 No.24', 'materi:book1:1:0'),
  (1, 'published', 24, 'Kosakata', '（　）に なにを いれますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', 'かいぎしつは（　）ですか。', '["どこ","だれ","いつ","なに"]'::jsonb, 0, 'どこ dipakai untuk menanyakan tempat.', 'Bab 1–5 · Mondai 3 No.25', 'materi:book1:2:0'),
  (1, 'published', 25, 'Kosakata', '（　）に なにを いれますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', '「これは あなたの かさですか。」「いいえ、（　）。」', '["ちがいます","そうです","そうですか","どうも"]'::jsonb, 0, 'ちがいます dipakai untuk menyangkal informasi yang salah. そうです dan そうですか dipakai untuk jawaban POSITIF/mengerti, bukan menyangkal, dan どうも adalah ungkapan terima kasih - ketiganya salah konteks di sini.', 'Bab 1–5 · Mondai 3 No.26', 'materi:book1:2:0'),
  (1, 'published', 26, 'Kosakata', '（　）に なにを いれますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', 'わたしは まいあさ 6じ（　）おきます。', '["に","で","と","へ"]'::jsonb, 0, 'に menandai waktu yang spesifik seperti jam.', 'Bab 1–5 · Mondai 3 No.27', 'materi:book1:3:0'),
  (1, 'published', 27, 'Kosakata', '（　）に なにを いれますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', 'げつようび（　）きんようびまで はたらきます。', '["から","まで","と","に"]'::jsonb, 0, 'から menunjukkan titik mulai, dipasangkan dengan まで.', 'Bab 1–5 · Mondai 3 No.28', 'materi:book1:3:0'),
  (1, 'published', 28, 'Kosakata', '（　）に なにを いれますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', 'わたしは でんしゃ（　）がっこうへ いきます。', '["で","へ","と","に"]'::jsonb, 0, 'で menandai alat transportasi yang dipakai.', 'Bab 1–5 · Mondai 3 No.29', 'materi:book1:4:0'),
  (1, 'published', 29, 'Kosakata', '（　）に なにを いれますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', 'ともだち（　）かえります。', '["と","へ","で","の"]'::jsonb, 0, 'と menunjukkan teman yang menyertai suatu kegiatan.', 'Bab 1–5 · Mondai 3 No.30', 'materi:book1:4:0'),
  (1, 'published', 30, 'Parafrasa', '＿＿＿の ぶんと だいたい おなじ いみの ぶんが あります。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', 'あのかたは せんせいです。', '["あのかたは がくせいです。","あのかたは きょうしです。","あのかたは いしゃです。","あのかたは かいしゃいんです。"]'::jsonb, 1, 'せんせい dan きょうし sama-sama berarti “guru”, meski きょうし lebih sering dipakai untuk menyebut profesi sendiri.', 'Bab 1–5 · Mondai 4 No.31', 'materi:book1:0:0'),
  (1, 'published', 31, 'Parafrasa', '＿＿＿の ぶんと だいたい おなじ いみの ぶんが あります。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', 'これは わたしの ほんです。', '["この ほんは わたしのです。","その ほんは あなたのです。","あの ほんは せんせいのです。","これは あなたの ほんです。"]'::jsonb, 0, 'これは Nです dapat diubah menjadi この Nは……のです, karena これ menggantikan “ini+benda” sedangkan この menerangkan benda yang disebut.', 'Bab 1–5 · Mondai 4 No.32', 'materi:book1:1:0'),
  (1, 'published', 32, 'Parafrasa', '＿＿＿の ぶんと だいたい おなじ いみの ぶんが あります。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', 'かいぎしつは どこですか。', '["かいぎしつは どちらですか。","かいぎしつは なんですか。","かいぎしつは だれですか。","かいぎしつは いつですか。"]'::jsonb, 0, 'どこ dan どちら sama-sama menanyakan tempat; どちら lebih sopan.', 'Bab 1–5 · Mondai 4 No.33', 'materi:book1:2:0'),
  (1, 'published', 33, 'Parafrasa', '＿＿＿の ぶんと だいたい おなじ いみの ぶんが あります。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', 'きょうは やすみです。', '["きょうは はたらきます。","きょうは はたらきません。","きょうは べんきょうします。","きょうは おわります。"]'::jsonb, 1, 'やすみ (hari libur) berarti tidak bekerja, jadi はたらきません paling sesuai.', 'Bab 1–5 · Mondai 4 No.34', 'materi:book1:3:0'),
  (1, 'published', 34, 'Parafrasa', '＿＿＿の ぶんと だいたい おなじ いみの ぶんが あります。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', 'わたしは ひとりで がっこうへ いきます。', '["わたしは ともだちと がっこうへ いきます。","わたしは かぞくと がっこうへ いきます。","わたしは だれとも がっこうへ いきません。","わたしは ともだちと かえります。"]'::jsonb, 2, 'ひとりで (sendirian) berarti tidak pergi bersama siapa pun, sepadan dengan だれとも～ません.', 'Bab 1–5 · Mondai 4 No.35', 'materi:book1:4:0'),
  (1, 'published', 35, 'Soal Cerita', 'Baca cerita pendek berikut, lalu jawab pertanyaannya.', 'ミラーさんは　IMCの　会社員です。学生じゃ　ありません。これは　ミラーさんの　傘ですか。……いいえ、違います。それは　山田さんのです。<br><small>この　傘は　だれのですか。</small>', '["ミラーさんの","山田さんの","IMCの","学生の"]'::jsonb, 1, 'Cerita menjawab langsung: “Apakah ini payung Miller?……Bukan, itu payung Yamada.” の menggantikan Kata Benda yang sudah disebut (Pel.1–2), jadi 山田さんの berarti “punya Sdr. Yamada”.', 'Bab 1–5 · Soal Cerita No.36', 'materi:book1:1:0'),
  (1, 'published', 36, 'Soal Cerita', 'Baca cerita pendek berikut, lalu jawab pertanyaannya.', 'この　本は　わたしのです。あの　コンピューターは　どこの　コンピューターですか。……日本の　コンピューターです。会社の　事務所は　2階です。<br><small>事務所は　どこですか。</small>', '["1階","2階","3階","4階"]'::jsonb, 1, 'Kalimat terakhir cerita menyebutkan “Kantor perusahaan di lantai 2”, memakai pola Kata Benda は tempat です (Pel.3) untuk menyatakan lokasi.', 'Bab 1–5 · Soal Cerita No.37', 'materi:book1:2:0'),
  (1, 'published', 37, 'Soal Cerita', 'Baca cerita pendek berikut, lalu jawab pertanyaannya.', 'お手洗いは　あそこです。銀行は　9時から　3時までです。わたしは　まいあさ　6時に　おきます。<br><small>銀行は　何時からですか。</small>', '["7時","8時","9時","10時"]'::jsonb, 2, 'Cerita menyatakan “Bank dari pukul 9 sampai pukul 3”, memakai pola～から～まで (Pel.4) untuk titik mulai dan titik akhir waktu.', 'Bab 1–5 · Soal Cerita No.38', 'materi:book1:3:0'),
  (1, 'published', 38, 'Soal Cerita', 'Baca cerita pendek berikut, lalu jawab pertanyaannya.', 'きのう　勉強しませんでした。あした　京都へ　行きます。電車で　行きます。<br><small>何で　京都へ　行きますか。</small>', '["バス","タクシー","電車","歩いて"]'::jsonb, 2, 'Kalimat terakhir cerita menyebutkan “Pergi dengan kereta rel listrik”, memakai pola Kata Benda（kendaraan）で行きます (Pel.5) untuk sarana transportasi.', 'Bab 1–5 · Soal Cerita No.39', 'materi:book1:4:0'),
  (1, 'published', 39, 'Soal Cerita', 'Baca cerita pendek berikut, lalu jawab pertanyaannya.', '先週　どこ［へ］も　行きませんでした。今週の　日曜日、家族と　京都へ　行きます。……いいですね。<br><small>だれと　京都へ　行きますか。</small>', '["一人で","友達と","家族と","先生と"]'::jsonb, 2, 'Cerita menyebutkan “Bersama keluarga pergi ke Kyoto”, memakai pola Kata Benda（orang）と Kata Kerja (Pel.5) untuk menyatakan teman melakukan sesuatu.', 'Bab 1–5 · Soal Cerita No.40', 'materi:book1:4:0');
